/**
 * Who a farm task belongs to.
 *
 * `farm_tasks.assigned_to` is the explicit choice Micheal makes on the task
 * form. When it is empty the answer depends on where the task came from:
 *   - automated tasks (generated by the nightly cron, or confirmed from a
 *     chef email) are the farm owner's to do;
 *   - a hand-written task with nobody picked is for anyone on the team.
 * Resolving this at read time keeps the generators untouched.
 *
 * Pure — tested in tests/lib/tasks/assign.test.ts.
 */

export const ANYONE_LABEL = "Anyone";

export interface AssignableTask {
  assigned_to: string | null;
  source: string;
}

export function isAutomatedSource(source: string): boolean {
  return source !== "manual";
}

/** The profile id the task belongs to, or null when it is for anyone. */
export function effectiveAssigneeId(task: AssignableTask, ownerId: string | null): string | null {
  if (task.assigned_to) return task.assigned_to;
  return isAutomatedSource(task.source) ? ownerId : null;
}

/** First name is enough on a phone-width chip ("Micheal Breedlove" → "Micheal"). */
export function shortPersonName(fullName: string | null | undefined): string | null {
  const first = fullName?.trim().split(/\s+/)[0];
  return first || null;
}

export interface WorkloadRow {
  /** null = tasks for anyone. */
  id: string | null;
  name: string;
  todo: number;
  upcoming: number;
}

/**
 * "Who has what": open tasks per person — due now vs coming up. People
 * first (busiest first), the shared "Anyone" pile last.
 */
export function summarizeWorkload(
  todo: { assignee_id: string | null; assignee_name: string | null }[],
  upcoming: { assignee_id: string | null; assignee_name: string | null }[],
): WorkloadRow[] {
  const rows = new Map<string, WorkloadRow>();
  const bump = (t: { assignee_id: string | null; assignee_name: string | null }, key: "todo" | "upcoming") => {
    const k = t.assignee_id ?? "";
    const row = rows.get(k) ?? { id: t.assignee_id, name: t.assignee_name ?? ANYONE_LABEL, todo: 0, upcoming: 0 };
    row[key] += 1;
    rows.set(k, row);
  };
  todo.forEach((t) => bump(t, "todo"));
  upcoming.forEach((t) => bump(t, "upcoming"));
  return Array.from(rows.values()).sort((a, b) => {
    if ((a.id === null) !== (b.id === null)) return a.id === null ? 1 : -1;
    return b.todo + b.upcoming - (a.todo + a.upcoming) || a.name.localeCompare(b.name);
  });
}
